// APPU Workflow Intent Router & Data Formatter
const items = $input.all();
return items.map(item => {
  const data = item.json.body || item.json;
  const isSyllabus = !!data.requested_syllabus;
  const isBooking = !!data.preferred_slot || data.source === 'Discovery_Call';

  return {
    json: {
      event_type: isSyllabus ? 'WHATSAPP_SYLLABUS_DISPATCH' : (isBooking ? 'DISCOVERY_CALL_RESERVATION' : 'LEAD_ONBOARDING'),
      user_name: data.user_name || 'Valued Learner',
      user_phone: data.user_phone || '',
      user_role: data.user_role || 'Student',
      grade: data.grade || 'Class 10th',
      requested_syllabus: data.requested_syllabus || 'CBSE Class 10 Science & Math Syllabus Guide',
      timestamp: data.timestamp || new Date().toISOString(),
      processed_at: new Date().toISOString(),
      appu_status: 'QUEUED_FOR_WHATSAPP_DELIVERY'
    }
  };
});

// Gupshup WhatsApp Dispatch Tool for n8n
// Uses built-in n8n $helpers.httpRequest (fixes 'fetch is not defined' ReferenceError)
const recipientPhone = $input.first().json.body?.user_phone || $fromAI('recipientPhone', '919380815125');
const messageText = $fromAI('messageText', 'Syllabus PDF or study quest notification');

const response = await $helpers.httpRequest({
  method: 'POST',
  url: 'https://api.gupshup.io/sm/api/v1/msg',
  headers: {
    'Cache-Control': 'no-cache',
    'Content-Type': 'application/x-www-form-urlencoded',
    'apikey': 'YOUR_GUPSHUP_API_KEY'
  },
  body: new URLSearchParams({
    channel: 'whatsapp',
    source: '919972965677',
    destination: recipientPhone,
    'message': JSON.stringify({
      type: 'text',
      text: messageText
    })
  }).toString()
});

return [{ json: { success: true, response } }];

return [{
  json: {
    success: true,
    status: 'DISPATCHED_TO_WHATSAPP_API',
    workflowTag: 'whatsapp-syllabus-sender',
    executionId: 'exec_wa_' + Date.now(),
    message: 'APPU has sent the requested CBSE syllabus directly to WhatsApp!',
    details: $input.first().json
  }
}];
